def find_minimal_edit(s_in, s_out):
    """Find the minimal edit that transforms s_in to s_out."""
    # Simple approach: check if we're adding/removing characters or just replacing
    if len(s_in) == len(s_out):
        # Same length - check for character replacements
        diff_positions = []
        for i, (c1, c2) in enumerate(zip(s_in, s_out)):
            if c1 != c2:
                diff_positions.append(i)

        if len(diff_positions) == 1:
            pos = diff_positions[0]
            return (s_in[pos], s_out[pos], pos)
        elif len(diff_positions) == 0:
            return ("", "", -1)  # No difference
        else:
            # Multiple differences - take first one
            pos = diff_positions[0]
            return (s_in[pos:pos+1], s_out[pos:pos+1], pos)
    else:
        # Different lengths - check if one is a substring of the other
        # This is complex, so let's try to be more careful
        # Check if we're prepending/appending/inserting
        if len(s_in) < len(s_out):
            # Adding characters
            # Check if s_in is a prefix of s_out
            if s_out.startswith(s_in):
                # Added characters at the end
                added = s_out[len(s_in):]
                return ("", added, len(s_in))
            else:
                # Check if we can find a pattern of insertion
                # Let's just say we're replacing the whole thing for simplicity
                return (s_in, s_out, 0)
        else:
            # Removing characters
            if s_in.startswith(s_out):
                # Removed characters from the end
                removed = s_in[len(s_out):]
                return (removed, "", len(s_out))
            else:
                # Check if we can find a pattern of removal
                # Let's just say we're replacing the whole thing for simplicity
                return (s_in, s_out, 0)

# Test with our changed pairs
changed = [(0, 'ebg', 'wbg'), (2, 'khfbz', 'didfbbz')]

for idx, s_in, s_out in changed:
    old_sub, new_sub, pos = find_minimal_edit(s_in, s_out)
    print(f"Pair {idx}: '{s_in}' -> '{s_out}'")
    print(f"  Minimal edit: '{old_sub}' -> '{new_sub}' at position {pos}")

